package com.autoverse.launcher.core.sound

import android.media.AudioManager
import android.media.ToneGenerator

/**
 * Phase E of the theme system: optional, synthesized confirmation sounds.
 * No bundled audio assets, no network, no microphone permission; the tone
 * is generated by the platform (original by construction). Off by default
 * and globally mutable; plays at low volume on the media stream so it
 * ducks under navigation and music rather than talking over them.
 */
object ThemeSoundManager {

    private var lastPlayedMs = 0L

    /** Short confirmation tone; rate-limited so rapid taps never spam. */
    fun playConfirmation() {
        val now = System.currentTimeMillis()
        if (now - lastPlayedMs < 400L) return
        lastPlayedMs = now
        val generator = try {
            ToneGenerator(AudioManager.STREAM_MUSIC, VOLUME_PERCENT)
        } catch (_: RuntimeException) {
            return // no audio device / resources exhausted: stay silent
        }
        try {
            generator.startTone(ToneGenerator.TONE_PROP_BEEP, DURATION_MS)
        } catch (_: Exception) {
        } finally {
            // ToneGenerator needs a beat to finish the tone before release.
            Thread.sleep(180)
            generator.release()
        }
    }

    private const val VOLUME_PERCENT = 35
    private const val DURATION_MS = 140
}
